use std :: borrow :: Cow ; use std :: io ; use std :: sync :: { Arc , Mutex } ; use anyhow :: Result ; use bstr :: ByteSlice ; use colored :: Colorize ; use forge_domain :: ConsoleWriter ; use forge_markdown_stream :: StreamdownRenderer ; use forge_spinner :: SpinnerManager ; impl < P : ConsoleWriter + 'static > SharedSpinner < P > { # [doc = " Creates a new shared spinner from a SpinnerManager."] pub fn new (spinner : SpinnerManager < P >) -> Self { Self (Arc :: new (Mutex :: new (spinner))) } # [doc = " Start the spinner with a message."] pub fn start (& self , message : Option < & str >) -> Result < () > { self . 0 . lock () . unwrap_or_else (| e | e . into_inner ()) . start (message) } # [doc = " Stop the active spinner if any."] pub fn stop (& self , message : Option < String >) -> Result < () > { self . 0 . lock () . unwrap_or_else (| e | e . into_inner ()) . stop (message) } # [doc = " Pause the active spinner if any."] pub fn pause (& self) { self . 0 . lock () . unwrap_or_else (| e | e . into_inner ()) . pause () } # [doc = " Resume the active spinner if any."] pub fn resume (& self) { self . 0 . lock () . unwrap_or_else (| e | e . into_inner ()) . resume () } # [doc = " Resets the stopwatch to zero."] pub fn reset (& self) { self . 0 . lock () . unwrap_or_else (| e | e . into_inner ()) . reset () } # [doc = " Writes a line to stdout, suspending the spinner if active."] pub fn write_ln (& self , message : impl ToString) -> Result < () > { self . 0 . lock () . unwrap_or_else (| e | e . into_inner ()) . write_ln (message) } # [doc = " Writes a line to stderr, suspending the spinner if active."] pub fn ewrite_ln (& self , message : impl ToString) -> Result < () > { self . 0 . lock () . unwrap_or_else (| e | e . into_inner ()) . ewrite_ln (message) } }